func (stager *Stager) selectAndFocusFeatureLocked(entry *navaidFeatureEntry, focusCamera bool) {
	if entry == nil {
		return
	}
	if stager.hiddenFeatures != nil {
		delete(stager.hiddenFeatures, entry.Key)
	}
	if stager.expandedFeatures == nil {
		stager.expandedFeatures = make(map[string]bool)
	}
	stager.expandedFeatures[entry.Key] = true

	if stager.expandedCategories == nil {
		stager.expandedCategories = make(map[string]bool)
	}
	catCode := entry.CategoryCode
	if catCode == "" {
		catCode = entry.FeatureKind
	}
	catBucketKey := fmt.Sprintf("CAT_%d_%s", entry.Group, catCode)
	ltrBucketKey := fmt.Sprintf("LTR_%d_%s_%s", entry.Group, catCode, navaidFirstLetter(entry.ShortLabel))
	stager.expandedCategories[catBucketKey] = true
	stager.expandedCategories[ltrBucketKey] = true

	switch entry.Group {
	case groupNavaidSystems:
		stager.isNavaidSystemsExpanded = true
	case groupRadioEquipment:
		stager.isRadioEquipmentExpanded = true
	case groupApproachGuidance:
		stager.isApproachGuidanceExpanded = true
	case groupWaypoints:
		stager.isWaypointsExpanded = true
	case groupIndications:
		stager.isIndicationsExpanded = true
	case groupCheckpointsAndRadars:
		stager.isCheckpointsAndRadarsExpanded = true
	}

	stager.selectedFeatureKey = entry.Key
	stager.focusOnSelected = focusCamera
	if entry.InspectFeature != nil {
		entry.InspectFeature(stager.probeForm)
	}
	stager.ux_tree()
	stager.ux_maplibre()
}

func (stager *Stager) ux_maplibre() {
	if stager.maplibreStage == nil {
		return
	}

	// Preserve existing camera if user clicked on the map without requesting tree auto-focus
	var prevLat, prevLon, prevZoom, prevBearing float64
	hasPrevCamera := false
	if existingViews := stager.maplibreStage.GetInstancesSorted[*maplibre.MapView](); len(existingViews) > 0 {
		mv := existingViews[0]
		prevLat = mv.Latitude
		prevLon = mv.Longitude
		prevZoom = mv.Zoom
		prevBearing = mv.Bearing
		hasPrevCamera = prevZoom > 0
	}

	stager.maplibreStage.Reset()

	pitch := 15.0
	if stager.extrude3D {
		pitch = 52.0
	}

	mapView := &maplibre.MapView{
		Name:      "AIXM Aeronautical Map",
		StyleURL:  "offline",
		Latitude:  49.0097,
		Longitude: 2.5479,
		Zoom:      7.0,
		Pitch:     pitch,
		Bearing:   prevBearing,
	}

	layerCoverage := &maplibre.Layer{Name: "Navaid & Radar Coverage Volumes", IsVisible: true}
	layerApproach := &maplibre.Layer{Name: "ILS / Approach Guidance Sectors", IsVisible: true}
	layerIndications := &maplibre.Layer{Name: "Radials, DME Indications & Component Links", IsVisible: true}
	layerSelected := &maplibre.Layer{Name: "Selected Navaid / Fix Highlight", IsVisible: true}
	layerWaypoints := &maplibre.Layer{Name: "Waypoints, Airspace Points & Checkpoints (SVG)", IsVisible: true}
	layerNavaids := &maplibre.Layer{Name: "Navaids, Approach Facilities & Radars (SVG)", IsVisible: true}

	var allCoords [][2]float64
	var selectedCoords [][2]float64

	cat := buildNavaidCatalog(stager.stage)
	visitedGMLPositions := make(map[*gml.DirectPositionType]bool)
	if stager.stage != nil && stager.stage.GmlStage != nil {
		for _, p := range stager.stage.GmlStage.GetInstancesSorted[*gml.DirectPositionType]() {
			if len(cat.Entries) > 0 {
				visitedGMLPositions[p] = true
			}
		}
	}

	for idx, entry := range cat.Entries {
		entry := entry
		if stager.hiddenFeatures != nil && stager.hiddenFeatures[entry.Key] {
			continue
		}
		isSelected := stager.selectedFeatureKey == entry.Key
		popup := buildNavaidPopupHTML(entry)
		fillColor, strokeColor := classifyNavaidColors(entry)

		onSelect := func() {
			stager.mu.Lock()
			defer stager.mu.Unlock()
			stager.selectAndFocusFeatureLocked(entry, false)
		}

		// 1. Coverage Ring / Service Volume Polygon (VOR/DME, NDB, Radars)
		if entry.HasCoord && entry.HasRangeRing && entry.VisualRadiusNM > 0 {
			ring := buildGeodesicCircleCoords(entry.Lat, entry.Lon, entry.VisualRadiusNM, 36)
			polyName := fmt.Sprintf("Range_%d_%s", idx+1, sanitizeMapID(entry.Key))
			baseAlt := 0.0
			if entry.HasElev && entry.ElevM > 0 {
				baseAlt = entry.ElevM
			}
			topAlt := baseAlt + entry.CeilingM
			if topAlt <= baseAlt+200 {
				topAlt = baseAlt + 2500.0
			}
			labelText := entry.Designator
			if labelText == "" {
				labelText = entry.ShortLabel
			}
			poly := &maplibre.Polygon{
				Name:            polyName,
				Label:           labelText,
				PopupHTML:       popup,
				FillColor:       fillColor,
				FillOpacity:     0.12,
				StrokeColor:     strokeColor,
				StrokeWidth:     1.8,
				StrokeOpacity:   0.78,
				IsExtruded:      stager.extrude3D,
				BaseAltitude:    baseAlt,
				ExtrusionHeight: topAlt,
				OnClick: func(_ *maplibre.Polygon) {
					onSelect()
				},
			}
			for ptIdx, pt := range ring {
				poly.Coordinates = append(poly.Coordinates, &maplibre.Coordinate{
					Name:      fmt.Sprintf("%s_pt_%d", polyName, ptIdx+1),
					Latitude:  pt[0],
					Longitude: pt[1],
					Altitude:  baseAlt,
				})
				if isSelected {
					selectedCoords = append(selectedCoords, pt)
				}
			}
			layerCoverage.Polygons = append(layerCoverage.Polygons, poly)

			if isSelected {
				hiPoly := &maplibre.Polygon{
					Name:            polyName + "_highlight",
					Label:           labelText,
					PopupHTML:       popup,
					FillColor:       "#ffea00",
					FillOpacity:     0.22,
					StrokeColor:     "#ff3d00",
					StrokeWidth:     4.0,
					StrokeOpacity:   1.0,
					IsExtruded:      stager.extrude3D,
					BaseAltitude:    baseAlt,
					ExtrusionHeight: topAlt + 60,
					OnClick: func(_ *maplibre.Polygon) {
						onSelect()
					},
				}
				for ptIdx, pt := range ring {
					hiPoly.Coordinates = append(hiPoly.Coordinates, &maplibre.Coordinate{
						Name:      fmt.Sprintf("%s_hpt_%d", polyName, ptIdx+1),
						Latitude:  pt[0],
						Longitude: pt[1],
						Altitude:  baseAlt,
					})
				}
				layerSelected.Polygons = append(layerSelected.Polygons, hiPoly)
			}
		}

		// 2. Approach Guidance Beam Wedge Polygon (Localizer / SDF / Azimuth)
		if entry.HasCoord && entry.HasSector && entry.SectorRadiusNM > 0 {
			outboundCourse := math.Mod(entry.BearingDeg+180.0, 360.0)
			wedge := buildApproachSectorCoords(entry.Lat, entry.Lon, outboundCourse, entry.HalfWidthDeg, entry.SectorRadiusNM)
			polyName := fmt.Sprintf("Sector_%d_%s", idx+1, sanitizeMapID(entry.Key))
			baseAlt := 0.0
			if entry.HasElev && entry.ElevM > 0 {
				baseAlt = entry.ElevM
			}
			topAlt := baseAlt + 1250.0
			labelText := entry.Designator
			if labelText == "" {
				labelText = entry.ShortLabel
			}
			secPoly := &maplibre.Polygon{
				Name:            polyName,
				Label:           labelText,
				PopupHTML:       popup,
				FillColor:       "#ec407a",
				FillOpacity:     0.26,
				StrokeColor:     "#880e4f",
				StrokeWidth:     2.2,
				StrokeOpacity:   0.92,
				IsExtruded:      stager.extrude3D,
				BaseAltitude:    baseAlt,
				ExtrusionHeight: topAlt,
				OnClick: func(_ *maplibre.Polygon) {
					onSelect()
				},
			}
			for ptIdx, pt := range wedge {
				secPoly.Coordinates = append(secPoly.Coordinates, &maplibre.Coordinate{
					Name:      fmt.Sprintf("%s_pt_%d", polyName, ptIdx+1),
					Latitude:  pt[0],
					Longitude: pt[1],
					Altitude:  baseAlt,
				})
				allCoords = append(allCoords, pt)
				if isSelected {
					selectedCoords = append(selectedCoords, pt)
				}
			}
			layerApproach.Polygons = append(layerApproach.Polygons, secPoly)

			// Approach extended centerline axis inside the feather
			farLat, farLon := destinationLatLon(entry.Lat, entry.Lon, outboundCourse, entry.SectorRadiusNM)
			axisLine := &maplibre.Polyline{
				Name:            polyName + "_centerline",
				Label:           fmt.Sprintf("%s %.0f°", labelText, entry.BearingDeg),
				PopupHTML:       popup,
				StrokeColor:     "#880e4f",
				StrokeWidth:     2.0,
				StrokeOpacity:   0.92,
				StrokeDashArray: "6,3",
				OnClick: func(_ *maplibre.Polyline) {
					onSelect()
				},
			}
			axisLine.Coordinates = []*maplibre.Coordinate{
				{Name: polyName + "_c0", Latitude: entry.Lat, Longitude: entry.Lon, Altitude: baseAlt + 30},
				{Name: polyName + "_c1", Latitude: farLat, Longitude: farLon, Altitude: topAlt},
			}
			layerIndications.Polylines = append(layerIndications.Polylines, axisLine)

			if entry.BackCourse {
				bcWedge := buildApproachSectorCoords(entry.Lat, entry.Lon, entry.BearingDeg, entry.HalfWidthDeg, entry.SectorRadiusNM*0.6)
				bcName := polyName + "_backcourse"
				bcPoly := &maplibre.Polygon{
					Name:            bcName,
					Label:           labelText + " BC",
					PopupHTML:       popup,
					FillColor:       "#ab47bc",
					FillOpacity:     0.16,
					StrokeColor:     "#6a1b9a",
					StrokeWidth:     1.6,
					StrokeOpacity:   0.82,
					IsExtruded:      stager.extrude3D,
					BaseAltitude:    baseAlt,
					ExtrusionHeight: baseAlt + 900.0,
					OnClick: func(_ *maplibre.Polygon) {
						onSelect()
					},
				}
				for ptIdx, pt := range bcWedge {
					bcPoly.Coordinates = append(bcPoly.Coordinates, &maplibre.Coordinate{
						Name:      fmt.Sprintf("%s_pt_%d", bcName, ptIdx+1),
						Latitude:  pt[0],
						Longitude: pt[1],
						Altitude:  baseAlt,
					})
				}
				layerApproach.Polygons = append(layerApproach.Polygons, bcPoly)
			}

			if isSelected {
				hiSec := &maplibre.Polygon{
					Name:            polyName + "_highlight",
					Label:           labelText,
					PopupHTML:       popup,
					FillColor:       "#ffea00",
					FillOpacity:     0.32,
					StrokeColor:     "#ff3d00",
					StrokeWidth:     4.2,
					StrokeOpacity:   1.0,
					IsExtruded:      stager.extrude3D,
					BaseAltitude:    baseAlt,
					ExtrusionHeight: topAlt + 50,
					OnClick: func(_ *maplibre.Polygon) {
						onSelect()
					},
				}
				for ptIdx, pt := range wedge {
					hiSec.Coordinates = append(hiSec.Coordinates, &maplibre.Coordinate{
						Name:      fmt.Sprintf("%s_hpt_%d", polyName, ptIdx+1),
						Latitude:  pt[0],
						Longitude: pt[1],
						Altitude:  baseAlt,
					})
				}
				layerSelected.Polygons = append(layerSelected.Polygons, hiSec)
			}
		}

		// 3. Displaced NavaidComponent Links (e.g. Composite ILS -> Localizer / Glidepath / MarkerBeacons)
		if entry.HasCoord && len(entry.DisplacedLinks) > 0 {
			for dIdx, dl := range entry.DisplacedLinks {
				linkName := fmt.Sprintf("CompLink_%d_%d_%s", idx+1, dIdx+1, sanitizeMapID(entry.Key))
				pl := &maplibre.Polyline{
					Name:            linkName,
					Label:           entry.Designator + " -> " + dl.TargetLabel,
					PopupHTML:       popup,
					StrokeColor:     "#455a64",
					StrokeWidth:     1.8,
					StrokeOpacity:   0.82,
					StrokeDashArray: "3,3",
					OnClick: func(_ *maplibre.Polyline) {
						onSelect()
					},
				}
				pl.Coordinates = []*maplibre.Coordinate{
					{Name: linkName + "_a", Latitude: entry.Lat, Longitude: entry.Lon, Altitude: entry.ElevM + 80},
					{Name: linkName + "_b", Latitude: dl.Lat, Longitude: dl.Lon, Altitude: entry.ElevM + 80},
				}
				layerIndications.Polylines = append(layerIndications.Polylines, pl)
			}
		}

		// 4. Radial / DME Distance / CheckpointVOR Polylines
		if entry.HasLine {
			lineName := fmt.Sprintf("Line_%d_%s", idx+1, sanitizeMapID(entry.Key))
			dashArray := ""
			lineWidth := 2.3
			startAlt := 350.0
			endAlt := 950.0
			switch entry.FeatureKind {
			case "DistanceIndication":
				dashArray = "6,4"
				lineWidth = 2.1
				startAlt = 420.0
				endAlt = 1050.0
			case "CheckpointVOR":
				dashArray = "4,3"
				lineWidth = 2.2
				startAlt = 180.0
				endAlt = 180.0
			}
			lineLbl := entry.LineMetricLabel
			if lineLbl == "" {
				lineLbl = entry.ShortLabel
			}
			pl := &maplibre.Polyline{
				Name:            lineName,
				Label:           lineLbl,
				PopupHTML:       popup,
				StrokeColor:     strokeColor,
				StrokeWidth:     lineWidth,
				StrokeOpacity:   0.88,
				StrokeDashArray: dashArray,
				OnClick: func(_ *maplibre.Polyline) {
					onSelect()
				},
			}
			pl.Coordinates = []*maplibre.Coordinate{
				{Name: lineName + "_from", Latitude: entry.FromLat, Longitude: entry.FromLon, Altitude: startAlt},
				{Name: lineName + "_to", Latitude: entry.ToLat, Longitude: entry.ToLon, Altitude: endAlt},
			}
			layerIndications.Polylines = append(layerIndications.Polylines, pl)
			allCoords = append(allCoords, [2]float64{entry.FromLat, entry.FromLon}, [2]float64{entry.ToLat, entry.ToLon})

			if isSelected {
				selectedCoords = append(selectedCoords, [2]float64{entry.FromLat, entry.FromLon}, [2]float64{entry.ToLat, entry.ToLon})
				hiLine := &maplibre.Polyline{
					Name:          lineName + "_highlight",
					Label:         lineLbl,
					PopupHTML:     popup,
					StrokeColor:   "#ff3d00",
					StrokeWidth:   5.2,
					StrokeOpacity: 1.0,
					OnClick: func(_ *maplibre.Polyline) {
						onSelect()
					},
				}
				hiLine.Coordinates = []*maplibre.Coordinate{
					{Name: lineName + "_hfrom", Latitude: entry.FromLat, Longitude: entry.FromLon, Altitude: startAlt + 20},
					{Name: lineName + "_hto", Latitude: entry.ToLat, Longitude: entry.ToLon, Altitude: endAlt + 20},
				}
				layerSelected.Polylines = append(layerSelected.Polylines, hiLine)
			}

			// For indications without their own physical point feature (AngleIndication / DistanceIndication),
			// place a compact radial/DME pill marker at the midpoint when selected (or on compact charts).
			if entry.FeatureKind == "AngleIndication" || entry.FeatureKind == "DistanceIndication" {
				if isSelected || len(cat.Entries) <= 45 {
					midLat := entry.FromLat*0.45 + entry.ToLat*0.55
					midLon := entry.FromLon*0.45 + entry.ToLon*0.55
					layerWaypoints.Markers = append(layerWaypoints.Markers, &maplibre.Marker{
						Name:              fmt.Sprintf("IndPill_%d_%s", idx+1, sanitizeMapID(entry.Key)),
						Label:             lineLbl,
						PopupHTML:         popup,
						Latitude:          midLat,
						Longitude:         midLon,
						Altitude:          (startAlt + endAlt) * 0.5,
						Color:             strokeColor,
						Scale:             1.0,
						RotationAlignment: maplibre.MarkerAlignmentViewport,
						PitchAlignment:    maplibre.MarkerAlignmentViewport,
						Anchor:            maplibre.MarkerAnchorCenter,
						SVG:               buildIndicationPillSVG(entry.CategoryCode, lineLbl, strokeColor, isSelected),
						OnClick: func(_ *maplibre.Marker) {
							onSelect()
						},
					})
				}
				continue
			}
		}

		// 5. Point / Station Aeronautical SVG Marker
		if !entry.HasCoord {
			continue
		}
		allCoords = append(allCoords, [2]float64{entry.Lat, entry.Lon})
		if isSelected {
			selectedCoords = append(selectedCoords, [2]float64{entry.Lat, entry.Lon})
			// Add a crisp selection halo ring around selected point/station so it stands out in 2D & 3D
			haloRing := buildGeodesicCircleCoords(entry.Lat, entry.Lon, 1.2, 24)
			haloName := fmt.Sprintf("SelHalo_%d_%s", idx+1, sanitizeMapID(entry.Key))
			haloPoly := &maplibre.Polygon{
				Name:            haloName,
				Label:           entry.ShortLabel,
				PopupHTML:       popup,
				FillColor:       "#ffea00",
				FillOpacity:     0.28,
				StrokeColor:     "#ff3d00",
				StrokeWidth:     3.6,
				StrokeOpacity:   1.0,
				IsExtruded:      stager.extrude3D,
				BaseAltitude:    entry.ElevM,
				ExtrusionHeight: entry.ElevM + 600.0,
				OnClick: func(_ *maplibre.Polygon) {
					onSelect()
				},
			}
			for ptIdx, pt := range haloRing {
				haloPoly.Coordinates = append(haloPoly.Coordinates, &maplibre.Coordinate{
					Name:      fmt.Sprintf("%s_pt_%d", haloName, ptIdx+1),
					Latitude:  pt[0],
					Longitude: pt[1],
					Altitude:  entry.ElevM,
				})
			}
			layerSelected.Polygons = append(layerSelected.Polygons, haloPoly)
		}

		markerAlt := 220.0
		if entry.HasElev && entry.ElevM > 0 {
			markerAlt = entry.ElevM + 180.0
		}
		if entry.HasRangeRing && entry.CeilingM > 0 {
			markerAlt = math.Max(markerAlt, entry.ElevM+entry.CeilingM+140.0)
		}

		marker := &maplibre.Marker{
			Name:              fmt.Sprintf("Mkr_%d_%s", idx+1, sanitizeMapID(entry.Key)),
			Label:             entry.ShortLabel,
			PopupHTML:         popup,
			Latitude:          entry.Lat,
			Longitude:         entry.Lon,
			Altitude:          markerAlt,
			Color:             strokeColor,
			Scale:             1.0,
			RotationAlignment: maplibre.MarkerAlignmentViewport,
			PitchAlignment:    maplibre.MarkerAlignmentViewport,
			Anchor:            maplibre.MarkerAnchorCenter,
			SVG:               buildAeronauticalSymbolSVG(entry, strokeColor, isSelected),
			OnClick: func(_ *maplibre.Marker) {
				onSelect()
			},
		}

		if entry.Group == groupWaypoints || entry.FeatureKind == "CheckpointVOR" || entry.FeatureKind == "CheckpointINS" {
			layerWaypoints.Markers = append(layerWaypoints.Markers, marker)
		} else {
			layerNavaids.Markers = append(layerNavaids.Markers, marker)
		}
	}

	// Fallback for any raw GML positions if no AIXM features were present
	if len(cat.Entries) == 0 && stager.stage != nil && stager.stage.GmlStage != nil {
		for _, pos := range stager.stage.GmlStage.GetInstancesSorted[*gml.DirectPositionType]() {
			if visitedGMLPositions[pos] {
				continue
			}
			if lat, lon, ok := parseDirectPositionLatLon(pos, pos.SrsName); ok {
				layerWaypoints.Markers = append(layerWaypoints.Markers, &maplibre.Marker{
					Name:              "Pos_" + pos.Name,
					Label:             pos.Name,
					Latitude:          lat,
					Longitude:         lon,
					Altitude:          200,
					Color:             "#1565c0",
					Scale:             1.0,
					RotationAlignment: maplibre.MarkerAlignmentViewport,
					PitchAlignment:    maplibre.MarkerAlignmentViewport,
					Anchor:            maplibre.MarkerAnchorCenter,
					PopupHTML:         pos.Name,
				})
				allCoords = append(allCoords, [2]float64{lat, lon})
			}
		}
	}

	candidateLayers := []*maplibre.Layer{
		layerCoverage,
		layerApproach,
		layerIndications,
		layerSelected,
		layerWaypoints,
		layerNavaids,
	}
	for _, l := range candidateLayers {
		if len(l.Polygons) > 0 || len(l.Polylines) > 0 || len(l.Markers) > 0 {
			mapView.Layers = append(mapView.Layers, l)
		}
	}

	if stager.focusOnSelected && len(selectedCoords) > 0 {
		cLat, cLon, zoom := computeNavaidViewport(selectedCoords)
		mapView.Latitude = cLat
		mapView.Longitude = cLon
		mapView.Zoom = zoom
		stager.focusOnSelected = false
		stager.resetCameraToBounds = false
	} else if !stager.resetCameraToBounds && hasPrevCamera {
		mapView.Latitude = prevLat
		mapView.Longitude = prevLon
		mapView.Zoom = prevZoom
	} else if len(allCoords) > 0 {
		cLat, cLon, zoom := computeNavaidViewport(allCoords)
		mapView.Latitude = cLat
		mapView.Longitude = cLon
		mapView.Zoom = zoom
		stager.resetCameraToBounds = false
	}

	stager.maplibreStage.StageBranch(mapView)
	stager.maplibreStage.Commit()
	stager.ux_cesium()
}

func sanitizeMapID(s string) string {
	var b strings.Builder
	b.Grow(len(s))
	for _, r := range s {
		if (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') || r == '_' {
			b.WriteRune(r)
		} else {
			b.WriteByte('_')
		}
	}
	return b.String()
}

func classifyNavaidColors(entry *navaidFeatureEntry) (fillColor, strokeColor string) {
	switch entry.FeatureKind {
	case "Navaid":
		up := strings.ToUpper(entry.CategoryCode)
		switch {
		case strings.Contains(up, "ILS"), strings.Contains(up, "LOC"), strings.Contains(up, "MLS"):
			return "#f06292", "#ad1457"
		case strings.Contains(up, "NDB"):
			return "#ab47bc", "#6a1b9a"
		case strings.Contains(up, "TACAN"):
			return "#26a69a", "#00695c"
		default:
			return "#42a5f5", "#0d47a1"
		}
	case "VOR":
		return "#42a5f5", "#1565c0"
	case "DME", "TACAN":
		return "#26a69a", "#00695c"
	case "NDB":
		return "#ab47bc", "#6a1b9a"
	case "Localizer", "Glidepath", "SDF", "Azimuth", "Elevation":
		return "#ec407a", "#ad1457"
	case "MarkerBeacon":
		switch strings.ToUpper(entry.CategoryCode) {
		case "OM", "OUTER":
			return "#29b6f6", "#0277bd"
		case "MM", "MIDDLE":
			return "#ffa726", "#ef6c00"
		default:
			return "#66bb6a", "#2e7d32"
		}
	case "DesignatedPoint":
		return "#263238", "#1a237e"
	case "SignificantPointInAirspace":
		return "#ff7043", "#d84315"
	case "AngleIndication":
		return "#5c6bc0", "#283593"
	case "DistanceIndication":
		return "#00acc1", "#006064"
	case "CheckpointVOR", "CheckpointINS":
		return "#ffb300", "#e65100"
	case "RadarSystem", "PrimarySurveillanceRadar", "SecondarySurveillanceRadar", "PrecisionApproachRadar":
		return "#00bcd4", "#006064"
	default:
		return "#78909c", "#37474f"
	}
}

func buildGeodesicCircleCoords(latDeg, lonDeg, radiusNM float64, segments int) [][2]float64 {
	if segments < 12 {
		segments = 24
	}
	ring := make([][2]float64, 0, segments+1)
	for i := 0; i <= segments; i++ {
		az := float64(i) * 360.0 / float64(segments)
		pLat, pLon := destinationLatLon(latDeg, lonDeg, az, radiusNM)
		ring = append(ring, [2]float64{pLat, pLon})
	}
	return ring
}

func buildApproachSectorCoords(latDeg, lonDeg, outboundBearingDeg, halfWidthDeg, radiusNM float64) [][2]float64 {
	const arcSteps = 8
	coords := make([][2]float64, 0, arcSteps+3)
	coords = append(coords, [2]float64{latDeg, lonDeg})
	startAz := outboundBearingDeg - halfWidthDeg
	step := (2.0 * halfWidthDeg) / float64(arcSteps)
	for i := 0; i <= arcSteps; i++ {
		az := math.Mod(startAz+float64(i)*step+360.0, 360.0)
		pLat, pLon := destinationLatLon(latDeg, lonDeg, az, radiusNM)
		coords = append(coords, [2]float64{pLat, pLon})
	}
	coords = append(coords, [2]float64{latDeg, lonDeg})
	return coords
}

func computeNavaidViewport(coords [][2]float64) (cLat, cLon, zoom float64) {
	if len(coords) == 0 {
		return 49.0097, 2.5479, 7.0
	}
	minLat, maxLat := coords[0][0], coords[0][0]
	minLon, maxLon := coords[0][1], coords[0][1]
	for _, c := range coords[1:] {
		if c[0] < minLat {
			minLat = c[0]
		}
		if c[0] > maxLat {
			maxLat = c[0]
		}
		if c[1] < minLon {
			minLon = c[1]
		}
		if c[1] > maxLon {
			maxLon = c[1]
		}
	}
	cLat = (minLat + maxLat) * 0.5
	cLon = (minLon + maxLon) * 0.5
	span := math.Max(maxLat-minLat, maxLon-minLon)
	switch {
	case span > 40:
		zoom = 3.4
	case span > 20:
		zoom = 4.4
	case span > 10:
		zoom = 5.2
	case span > 5:
		zoom = 6.2
	case span > 2:
		zoom = 7.3
	case span > 0.8:
		zoom = 8.6
	case span > 0.2:
		zoom = 10.2
	default:
		zoom = 11.4
	}
	return cLat, cLon, zoom
}

func escHTML(s string) string {
	s = strings.ReplaceAll(s, "&", "&amp;")
	s = strings.ReplaceAll(s, "<", "&lt;")
	s = strings.ReplaceAll(s, ">", "&gt;")
	s = strings.ReplaceAll(s, `"`, "&quot;")
	return s
}

func buildNavaidPopupHTML(entry *navaidFeatureEntry) string {
	var b strings.Builder
	cat := entry.CategoryCode
	if cat == "" {
		cat = entry.FeatureKind
	}
	head := entry.Designator
	if entry.FullName != "" && !strings.EqualFold(entry.FullName, entry.Designator) {
		if head != "" {
			head += " — " + entry.FullName
		} else {
			head = entry.FullName
		}
	}
	if head == "" {
		head = entry.ShortLabel
	}
	fmt.Fprintf(&b, "<b>[%s] %s</b>", escHTML(cat), escHTML(head))
	fmt.Fprintf(&b, "<br/><i>AIXM Feature: %s</i>", escHTML(entry.FeatureKind))
	if entry.FreqOrChannel != "" {
		fmt.Fprintf(&b, "<br/><b>Freq / Channel:</b> %s", escHTML(entry.FreqOrChannel))
	}
	if entry.LineMetricLabel != "" {
		fmt.Fprintf(&b, "<br/><b>Indication:</b> %s", escHTML(entry.LineMetricLabel))
	}
	if entry.HasCoord {
		fmt.Fprintf(&b, "<br/><b>Position:</b> %.5f°, %.5f°", entry.Lat, entry.Lon)
	}
	if entry.ElevLabel != "" {
		fmt.Fprintf(&b, "<br/><b>Elevation:</b> %s", escHTML(entry.ElevLabel))
	}
	if entry.AirportOrAirspaceRef != "" {
		fmt.Fprintf(&b, "<br/><b>Aerodrome / Airspace:</b> %s", escHTML(entry.AirportOrAirspaceRef))
	}
	if entry.StatusSummary != "" {
		fmt.Fprintf(&b, "<br/><b>Status:</b> %s", escHTML(entry.StatusSummary))
	}
	if entry.MonitoringSummary != "" {
		fmt.Fprintf(&b, "<br/><b>Monitoring:</b> %s", escHTML(entry.MonitoringSummary))
	}
	for _, kv := range entry.ExtraProps {
		fmt.Fprintf(&b, "<br/><b>%s:</b> %s", escHTML(kv[0]), escHTML(kv[1]))
	}
	if len(entry.Components) > 0 {
		var cNames []string
		for _, c := range entry.Components {
			lbl := formatXlinkRefLabel(c.Title, c.Href)
			if lbl != "" {
				cNames = append(cNames, lbl)
			}
		}
		if len(cNames) > 0 {
			fmt.Fprintf(&b, "<br/><b>Equipment:</b> %s", escHTML(strings.Join(cNames, ", ")))
		}
	}
	if len(entry.Authorities) > 0 {
		var aNames []string
		for _, a := range entry.Authorities {
			aNames = append(aNames, fmt.Sprintf("%s: %s", a.Role, a.OrgLabel))
		}
		fmt.Fprintf(&b, "<br/><b>Authorities:</b> %s", escHTML(strings.Join(aNames, " | ")))
	}
	for _, n := range entry.Notes {
		if n.Text != "" {
			txt := n.Text
			if len(txt) > 140 {
				txt = txt[:140] + "..."
			}
			fmt.Fprintf(&b, "<br/><small>%s</small>", escHTML(txt))
		}
	}
	return b.String()
}

func buildIndicationPillSVG(kindCode, metric, color string, isSelected bool) string {
	txt := metric
	if kindCode != "" && !strings.Contains(txt, kindCode) {
		txt = kindCode + " " + txt
	}
	if len(txt) > 20 {
		txt = txt[:20]
	}
	w := len(txt)*7 + 16
	if w < 64 {
		w = 64
	}
	bg := "#ffffff"
	stroke := color
	sw := "1.6"
	if isSelected {
		bg = "#fff9c4"
		stroke = "#ff3d00"
		sw = "2.8"
	}
	return fmt.Sprintf(
		`<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="22" viewBox="0 0 %d 22">`+
			`<rect x="1" y="1" width="%d" height="20" rx="10" fill="%s" fill-opacity="0.94" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
			`<text x="%d" y="15" text-anchor="middle" font-family="monospace, sans-serif" font-size="10" font-weight="bold" fill="%s">%s</text>`+
			`</svg>`,
		w, w, w-2, bg, stroke, sw, w/2, color, escHTML(txt),
	)
}

func buildAeronauticalSymbolSVG(entry *navaidFeatureEntry, color string, isSelected bool) string {
	borderColor := color
	bgFill := "#ffffff"
	sw := "2.0"
	if isSelected {
		borderColor = "#ff3d00"
		bgFill = "#fff9c4"
		sw = "2.8"
	}

	// Compact ICAO 5-letter Waypoint / SignificantPoint / Checkpoint symbol + label
	if entry.FeatureKind == "DesignatedPoint" || entry.FeatureKind == "SignificantPointInAirspace" ||
		entry.FeatureKind == "CheckpointVOR" || entry.FeatureKind == "CheckpointINS" {
		lbl := entry.Designator
		if lbl == "" {
			lbl = entry.ShortLabel
		}
		if len(lbl) > 14 {
			lbl = lbl[:14]
		}
		w := len(lbl)*7 + 28
		if w < 72 {
			w = 72
		}
		var icon string
		switch entry.FeatureKind {
		case "SignificantPointInAirspace":
			icon = fmt.Sprintf(
				`<circle cx="12" cy="12" r="8" fill="%s" fill-opacity="0.92" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
					`<polygon points="12,5 18,12 12,19 6,12" fill="%s" fill-opacity="0.88" stroke="%s" stroke-width="1.2" stroke-opacity="1.0"/>`,
				bgFill, borderColor, sw, color, borderColor,
			)
		case "CheckpointVOR", "CheckpointINS":
			icon = fmt.Sprintf(
				`<circle cx="12" cy="12" r="8" fill="%s" fill-opacity="0.94" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
					`<line x1="4" y1="12" x2="20" y2="12" stroke="%s" stroke-width="1.5" stroke-opacity="1.0"/>`+
					`<line x1="12" y1="4" x2="12" y2="20" stroke="%s" stroke-width="1.5" stroke-opacity="1.0"/>`+
					`<circle cx="12" cy="12" r="2.5" fill="%s"/>`,
				bgFill, borderColor, sw, borderColor, borderColor, color,
			)
		default:
			// Standard ICAO 4-star / triangle Reporting Waypoint
			icon = fmt.Sprintf(
				`<polygon points="12,3 21,19 3,19" fill="%s" fill-opacity="0.92" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
					`<circle cx="12" cy="14" r="2.2" fill="%s"/>`,
				bgFill, borderColor, sw, color,
			)
		}
		return fmt.Sprintf(
			`<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="24" viewBox="0 0 %d 24">`+
				`%s`+
				`<rect x="24" y="3" width="%d" height="18" rx="3" fill="%s" fill-opacity="0.92" stroke="%s" stroke-width="1.2" stroke-opacity="0.9"/>`+
				`<text x="%d" y="15.5" text-anchor="middle" font-family="monospace, sans-serif" font-size="10.5" font-weight="bold" fill="%s">%s</text>`+
				`</svg>`,
			w, w, icon, w-25, bgFill, borderColor, 24+(w-25)/2, color, escHTML(lbl),
		)
	}

	// Navaids, Equipment, Approach Guidance & Surveillance Radars:
	// Top ICAO symbol centered above callout box [Designator + Type | Frequency/Channel]
	title := entry.Designator
	if title == "" {
		title = entry.ShortLabel
	}
	if entry.CategoryCode != "" && !strings.EqualFold(title, entry.CategoryCode) {
		title = fmt.Sprintf("%s [%s]", title, entry.CategoryCode)
	}
	if len(title) > 22 {
		title = title[:22]
	}
	sub := entry.FreqOrChannel
	if len(sub) > 24 {
		sub = sub[:24]
	}

	boxW := 104
	if len(title)*7+16 > boxW {
		boxW = len(title)*7 + 16
	}
	if len(sub)*6+16 > boxW {
		boxW = len(sub)*6 + 16
	}
	boxH := 32
	if sub == "" {
		boxH = 20
	}
	totalH := 28 + boxH
	cx := boxW / 2

	upperCat := strings.ToUpper(entry.CategoryCode)
	var sym string
	switch {
	case strings.Contains(upperCat, "VOR_DME"), strings.Contains(upperCat, "VORTAC"):
		// VOR Hexagon enclosed inside DME Square + center dot
		sym = fmt.Sprintf(
			`<rect x="%d" y="2" width="24" height="22" rx="2" fill="%s" fill-opacity="0.94" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
				`<polygon points="%d,4 %d,9 %d,17 %d,22 %d,17 %d,9" fill="none" stroke="%s" stroke-width="1.8" stroke-opacity="1.0"/>`+
				`<circle cx="%d" cy="13" r="2.6" fill="%s"/>`,
			cx-12, bgFill, borderColor, sw,
			cx, cx+9, cx+9, cx, cx-9, cx-9, color,
			cx, color,
		)
	case entry.FeatureKind == "VOR" || upperCat == "VOR" || upperCat == "DVOR":
		// ICAO VOR Hexagon + center dot
		sym = fmt.Sprintf(
			`<polygon points="%d,2 %d,8 %d,18 %d,24 %d,18 %d,8" fill="%s" fill-opacity="0.94" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
				`<circle cx="%d" cy="13" r="2.8" fill="%s"/>`,
			cx, cx+11, cx+11, cx, cx-11, cx-11, bgFill, borderColor, sw,
			cx, color,
		)
	case entry.FeatureKind == "DME" || entry.FeatureKind == "TACAN" || upperCat == "TACAN" || upperCat == "DME":
		// DME / TACAN Box + side lobes + center dot
		sym = fmt.Sprintf(
			`<rect x="%d" y="3" width="22" height="20" rx="2" fill="%s" fill-opacity="0.94" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
				`<rect x="%d" y="9" width="28" height="8" rx="1" fill="none" stroke="%s" stroke-width="1.4" stroke-opacity="1.0"/>`+
				`<circle cx="%d" cy="13" r="2.8" fill="%s"/>`,
			cx-11, bgFill, borderColor, sw,
			cx-14, color,
			cx, color,
		)
	case entry.FeatureKind == "NDB" || strings.Contains(upperCat, "NDB"):
		// ICAO NDB Concentric Dashed/Dotted Rings + center dot
		sym = fmt.Sprintf(
			`<circle cx="%d" cy="13" r="11" fill="%s" fill-opacity="0.90" stroke="%s" stroke-width="%s" stroke-dasharray="3,2" stroke-opacity="1.0"/>`+
				`<circle cx="%d" cy="13" r="7" fill="none" stroke="%s" stroke-width="1.5" stroke-dasharray="2,2" stroke-opacity="1.0"/>`+
				`<circle cx="%d" cy="13" r="2.8" fill="%s"/>`,
			cx, bgFill, borderColor, sw,
			cx, color,
			cx, color,
		)
	case entry.FeatureKind == "MarkerBeacon":
		// Elliptical Marker Beacon Lens
		sym = fmt.Sprintf(
			`<ellipse cx="%d" cy="13" rx="13" ry="8" fill="%s" fill-opacity="0.92" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
				`<circle cx="%d" cy="13" r="2.6" fill="%s"/>`,
			cx, bgFill, borderColor, sw, cx, color,
		)
	case strings.Contains(entry.FeatureKind, "Radar"):
		// Surveillance Radar Sweep Ring + Dish Cross
		sym = fmt.Sprintf(
			`<circle cx="%d" cy="13" r="11" fill="%s" fill-opacity="0.92" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
				`<path d="M %d 7 A 7 7 0 0 1 %d 19" fill="none" stroke="%s" stroke-width="2.0" stroke-opacity="1.0"/>`+
				`<line x1="%d" y1="13" x2="%d" y2="6" stroke="%s" stroke-width="1.8" stroke-opacity="1.0"/>`+
				`<circle cx="%d" cy="13" r="2.4" fill="%s"/>`,
			cx, bgFill, borderColor, sw,
			cx-4, cx+4, color,
			cx, cx+7, color,
			cx, color,
		)
	default:
		// ILS / Localizer / Glidepath / SDF / Azimuth Precision Diamond
		sym = fmt.Sprintf(
			`<polygon points="%d,2 %d,13 %d,24 %d,13" fill="%s" fill-opacity="0.94" stroke="%s" stroke-width="%s" stroke-opacity="1.0"/>`+
				`<line x1="%d" y1="6" x2="%d" y2="20" stroke="%s" stroke-width="1.6" stroke-opacity="1.0"/>`+
				`<line x1="%d" y1="13" x2="%d" y2="13" stroke="%s" stroke-width="1.6" stroke-opacity="1.0"/>`,
			cx, cx+11, cx, cx-11, bgFill, borderColor, sw,
			cx, cx, color,
			cx-7, cx+7, color,
		)
	}

	if sub == "" {
		return fmt.Sprintf(
			`<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d">`+
				`%s`+
				`<rect x="1" y="27" width="%d" height="%d" rx="4" fill="%s" fill-opacity="0.95" stroke="%s" stroke-width="1.6" stroke-opacity="1.0"/>`+
				`<text x="%d" y="41" text-anchor="middle" font-family="monospace, sans-serif" font-size="10.5" font-weight="bold" fill="%s">%s</text>`+
				`</svg>`,
			boxW, totalH, boxW, totalH,
			sym,
			boxW-2, boxH-2, bgFill, borderColor,
			cx, color, escHTML(title),
		)
	}

	return fmt.Sprintf(
		`<svg xmlns="http://www.w3.org/2000/svg" width="%d" height="%d" viewBox="0 0 %d %d">`+
			`%s`+
			`<rect x="1" y="27" width="%d" height="%d" rx="4" fill="%s" fill-opacity="0.95" stroke="%s" stroke-width="1.6" stroke-opacity="1.0"/>`+
			`<text x="%d" y="39" text-anchor="middle" font-family="monospace, sans-serif" font-size="10.5" font-weight="bold" fill="%s">%s</text>`+
			`<line x1="6" y1="43" x2="%d" y2="43" stroke="%s" stroke-width="0.8" stroke-opacity="0.65"/>`+
			`<text x="%d" y="54" text-anchor="middle" font-family="monospace, sans-serif" font-size="9.5" fill="#263238">%s</text>`+
			`</svg>`,
		boxW, totalH, boxW, totalH,
		sym,
		boxW-2, boxH-2, bgFill, borderColor,
		cx, color, escHTML(title),
		boxW-6, color,
		cx, escHTML(sub),
	)
}
